INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-KAYALI-PISTACHIO-33','KAYALI','Yum Pistachio Gelato | 33 Eau de Parfum Intense 100 ml','العطور','العطور','يفتتح العطر بنفحات جيلاتو الفستق والبندق مع لمسة برغموت، ثم تظهر حلاوة الكريمة المخفوقة والمارشميلو. يعطي إحساساً مرحاً ومريحاً يليق بطلعة قهوة أو بأمسية هادئة.','{"nameAr":"كيالي يَم بيستاشيو جيلاتو 33 · أو دو بارفان إنتنس 100 مل","tagline":"فستق كريمي وحلاوة خفيفة تشبه أول ملعقة جيلاتو","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["جيلاتو الفستق والبندق والبرغموت","كريمة مخفوقة ومارشميلو وغزل البنات"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Yum Pistachio Gelato | 33 Eau de Parfum Intense 100 ml","tagline":"Creamy pistachio with the sweetness of a first spoonful of gelato","description":"Pistachio gelato and hazelnut open with a touch of bergamot, followed by the sweetness of whipped cream and marshmallow. A playful, comforting scent for coffee dates or quiet evenings.","benefits":["Pistachio gelato, hazelnut and bergamot","Whipped cream, marshmallow and cotton candy"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',9900,9900,0,'/media/catalog/TSPF-KAYALI-PISTACHIO-33-9786f70b03f7.webp','https://kayali.com/en-ae/products/yum-pistachio-gelato-33','KAYALI',24,1,1) ON CONFLICT(id) DO NOTHING;
