INSERT INTO products (id,brand,name,category,subcategory,description,details_json,reference_price_fils,price_fils,discount_percent,image_url,source_url,source_shop,stock,approved,active) VALUES ('TSPF-KAYALI-MARSHMALLOW-81','KAYALI','Yum Boujee Marshmallow | 81 Eau de Parfum Intense 100 ml','العطور','العطور','حلاوة الفراولة والمارشميلو الوردي تنسجم مع فانيلا مخفوقة ولمسة جوز الهند. رائحة تشبه حلوى الفراولة بالكريمة وتمنحك إحساساً ناعماً ومرحاً في الطلعات اليومية.','{"nameAr":"كيالي يَم بوجي مارشميلو 81 · أو دو بارفان إنتنس 100 مل","tagline":"فراولة ومارشميلو وردي بلمسة فانيلا ناعمة","productType":"fragrance","size":"100 مل","collection":"beauty","koreanCare":false,"imageType":"photo","benefits":["مارشميلو وردي وفراولة","رقائق جوز الهند وفانيلا مخفوقة ومسك وردي"],"howToUse":"رُشّ العطر على المعصم أو الرقبة واتركه يجف.","notes":"للاستخدام الخارجي. راجع قائمة المكونات المطبوعة على العبوة إذا كانت لديك حساسية من العطور.","en":{"name":"Yum Boujee Marshmallow | 81 Eau de Parfum Intense 100 ml","tagline":"Strawberry and pink marshmallow with soft whipped vanilla","description":"Strawberry and pink marshmallow meet whipped vanilla and a hint of coconut. The scent recalls strawberries and cream and brings a soft, playful feel to everyday outings.","benefits":["Pink marshmallow and strawberry","Coconut flakes, whipped vanilla and pink musk"],"howToUse":"Spray on your wrists or neck and let it dry.","notes":"For external use. Check the ingredient list on the packaging if you are sensitive to fragrances.","size":"100 ml"}}',9900,9900,0,'/media/catalog/TSPF-KAYALI-MARSHMALLOW-81-59eb7e21aeff.webp','https://us.kayali.com/products/yum-boujee-marshmallow-81','KAYALI',24,1,1) ON CONFLICT(id) DO NOTHING;
